css:
/* 猫猫星绘 · 黑白画室：白底黑字、1px 黑框、直角、按下变黑 */
#meow-dialog,#meow-viewer,#meow-gallery-picker,#meow-mask-editor{background:#fff!important;color:#171717!important;border:1px solid #171717!important;border-radius:0!important;box-shadow:6px 6px 0 #0002!important}
#meow-dialog::backdrop,#meow-viewer::backdrop,#meow-gallery-picker::backdrop,#meow-mask-editor::backdrop{background:#0006;backdrop-filter:none}
#meow-panel{--meow-ink:#171717;--meow-border:#222;background:#fff;color:#171717;font-family:system-ui,-apple-system,sans-serif}
#meow-panel .meow-header{border-bottom:1px solid #171717;padding:16px 0 10px}
#meow-panel h2{color:#171717;letter-spacing:2px;font-size:1.1em}
#meow-panel .meow-header p{font:11px/1.6 ui-monospace,monospace;letter-spacing:2px;color:#555}
#meow-panel h3,#meow-panel h4,#meow-panel [data-view=tools] h4{color:#171717;letter-spacing:1px;border-color:#ddd}
#meow-panel label{color:#171717}
#meow-panel .meow-tabs{background:#fff;border-bottom:1px solid #171717;gap:0}
#meow-panel .meow-tabs button[data-page]{border:1px solid #171717;border-right-width:0;border-radius:0;background:#fff;color:#171717}
#meow-panel .meow-tabs button[data-page]:nth-last-of-type(1){border-right-width:1px}
#meow-panel .meow-tabs button[aria-pressed=true]{background:#171717;color:#fff;border-color:#171717}
#meow-panel #meow-close-top{border:0;background:transparent;color:#171717}
#meow-panel button,#meow-panel .meow-file,#meow-viewer button,#meow-viewer a,#meow-gallery-picker button,#meow-mask-editor button{border:1px solid #222;border-radius:0;background:#fff;color:#171717;box-shadow:none}
#meow-panel button:hover,#meow-viewer button:hover,#meow-gallery-picker button:hover,#meow-mask-editor button:hover{background:#171717;color:#fff}
#meow-panel button:disabled{opacity:.5}
#meow-panel .meow-primary{background:#171717;color:#fff;letter-spacing:2px;text-align:left;padding-left:16px}
#meow-panel .meow-primary:hover{background:#fff;color:#171717}
#meow-panel input:not([type=checkbox]):not([type=file]):not([type=range]),#meow-panel select,#meow-panel textarea,#meow-mask-editor input{border:1px solid #222;border-radius:0;background:#fff;color:#171717}
#meow-panel input::placeholder,#meow-panel textarea::placeholder{color:#999}
#meow-panel input[type=checkbox],#meow-panel input[type=range],#meow-mask-editor input[type=range]{accent-color:#111}
#meow-panel :focus-visible,#meow-viewer :focus-visible{outline:2px solid #444;outline-offset:2px}
#meow-panel details.meow-fold,#meow-panel details.meow-list,#meow-panel details.meow-tools,#meow-panel .meow-quick,#meow-panel .meow-source,#meow-panel .meow-scene,#meow-panel .meow-tool-item{border:1px solid #bbb;border-radius:0;background:#fff}
#meow-panel details.meow-fold>summary::before,#meow-panel details.meow-list>summary::before,#meow-panel details.meow-tools>summary::before{color:#171717}
#meow-panel details[open].meow-fold>summary,#meow-panel details[open].meow-list>summary{border-bottom:1px solid #ddd}
#meow-panel .meow-fold-preview{color:#777}
#meow-panel .meow-presets{border-bottom:1px solid #ddd}
#meow-panel small,#meow-panel small.meow-hint-text{color:#555}
#meow-panel small.meow-hint-text{background:#f5f5f5;border-left:2px solid #171717;border-radius:0}
#meow-panel .meow-hint-dot{background:#fff;color:#171717;border:1px solid #171717}
#meow-panel .meow-hint-dot[aria-expanded=true]{background:#171717;color:#fff}
#meow-panel .meow-dot{background:#171717;border-radius:0}
#meow-panel #meow-tools-badge,#meow-panel #meow-tools-badge-page,#meow-panel #meow-vibe-summary,#meow-panel #meow-update-state{color:#171717}
#meow-panel .meow-thumb,#meow-gallery-picker .meow-pick-item{background:repeating-linear-gradient(45deg,#fff,#fff 12px,#f0f0f0 12px,#f0f0f0 13px);border:1px solid #111;border-radius:0}
#meow-panel .meow-thumb img,#meow-panel .meow-tool-stack img,#meow-panel .meow-tool-item>.meow-tool-thumb,#meow-panel .meow-vibe-row .meow-tool-thumb{border-radius:0}
#meow-panel .meow-vibe-row{border-bottom:1px solid #eee}
#meow-panel #meow-status{font:12px/1.6 ui-monospace,monospace;border-top:1px solid #171717;padding-top:8px}
#meow-panel #meow-close{background:#fff}
#meow-viewer pre{background:#f5f5f5;border-radius:0;border-left:2px solid #171717}
#meow-viewer .meow-use{border:1px solid #bbb;border-radius:0}
#meow-mask-editor canvas{border-radius:0}
.meow-inline-card button{border-radius:0!important;border:1px solid #222!important;background:#fff!important;color:#171717!important}
.meow-message-generate{border-radius:0!important;border:1px solid #222!important;background:#fff!important;color:#171717!important}
#meow-panel details.meow-drawing-params,#meow-panel [data-view] > details:not(.meow-fold):not(.meow-list):not(.meow-tools){border:1px solid #bbb;border-radius:0;background:#fff;padding:0 10px}
#meow-panel details > summary{color:#171717}
#meow-panel pre{background:#f5f5f5;border-radius:0}
#meow-panel details.meow-drawing-params,#meow-panel [data-view] > details:not(.meow-fold):not(.meow-list):not(.meow-tools){margin:10px 0}
#meow-panel details.meow-drawing-params > summary,#meow-panel [data-view] > details:not(.meow-fold):not(.meow-list):not(.meow-tools) > summary{padding:10px 2px;color:#171717!important;font-size:.9em}
